const a=(path,text)=>`<a href="${esc(path)}">${text}</a>`;
const tag=t=>t?`<span class="topic-tag ${t==='精华'?'gold':''}">${t}</span>`:'';
function floor(who,number,date,content,attrs=''){const p=PEOPLE[who]||{name:who,role:'注册用户',avatar:7,registered:'2022-09-05'};return `<article class="floor"><aside class="author"><a class="author-name" href="index.html?q=${encodeURIComponent(p.name)}">${esc(p.name)}</a><img class="avatar" src="assets/avatar-${p.avatar??7}.svg" alt="${esc(p.name)}的头像"><div class="rank">${esc(p.role)}</div><p>积分 ${who==='feixing'?682:145+Number(number)*13}</p><p>注册 ${p.registered||'2022-09-05'}</p><p>当前离线</p></aside><div class="post"><div class="post-top"><span>发表于 ${date}　<span>只看该作者</span></span><span>${number===1?'楼主':number+'#'}</span></div><div class="post-content" ${attrs}>${content}</div><div class="post-footer"><span>IP属地：校内网</span><span>来自 青禾校园网客户端</span><span><button data-like>赞</button>　<button data-report>举报</button>　回复</span></div></div></article>`;}
const report=(id,title)=>`<button class="attachment" type="button" data-preview="${id}"><img src="assets/${id==='reportBy'?'report-by':'report-anonymous'}.svg" alt="${title}缩略图" loading="lazy"><span>${title}<small>查看原图 · 去标识副本</small><small>JPG / 接收时原尺寸保留</small></span></button>`;
function bodies(id){switch(id){
 case 'reports':return floor('by',1,'2025-03-30 16:12',`<p>那张“第三个阳性”的图，今天又绕回我们班了。有人把名字跟我们寝排了一遍，排完还问我是不是益达。</p><p>我先把我那张放下面。15号去医院，18号乌鸡也查出来了。他不想写这些，让我说一声就行。第三张是别人转给我的，没带原文件，我也不知道最早谁发的。</p><p>14号语文周测我确实跑了一上午厕所。这个没什么好狡辩的。但别拿“谁也拉过肚子”接着往下排了，班里最近拉肚子的人多了去了。</p><div id="by-report">${report('reportBy','我自己留的那份')}</div><p style="margin-top:16px" id="anonymous">别人转来的：</p>${report('anonymous','那张被转发的图')}<p style="margin-top:16px">我现在脑子也有点乱。益达之前说他也不舒服，后来又叫人删照片。两个事凑一起，我当时确实想多了。先查清楚再说吧。</p>`)+floor('jie',2,'2025-03-30 16:27',`<p>面是我从食堂带的，回寝室才拌。洗澡前叫by帮我弄一下，乌鸡正好过来，俩人吃了几口。益达拿的是自己的汤。</p><p>账我还有。以前那篇${a('index.html?q=夜宵','夜宵认领帖')}里有照片，别凭想象给我加菜。</p>`)+floor('yida',3,'2025-03-30 16:46',`<p>我叫人删的是去年那几张，不是医院的。你不记得编号总记得那个信封吧。</p><p>我把能给你看的几页放编辑柜了，${a('pan/index.html?file=photoIndex','照片袋目录')}不用登号。别的私人东西就别翻了。</p>`, '')+floor('wanjun',4,'2025-03-30 17:02',`<p>我上周也跑医院了，查了没有。别看见拉肚子就把名字往那张图上安。</p>`)+floor('feixing',5,'2025-03-30 17:20',`<p>这里贴的图我留了接收记录。要查旧投稿按${a('index.html?thread=archive','原来的阅览办法')}来，别在评论区发别人的名字和病历。</p><p>有同学问周五谁在学校，摄影社的原贴没删，搜“摄影社”就有。别拿一张背影图认人。</p>`)+floor('feixing',6,'2025-03-30 17:24',`<div class="moderated">[该回复已被版主 飞星 屏蔽：请勿在公共版面散播未核实传言]<br>原回复时间 03-25 21:06　处理编号 Q0325-07<br>引用材料已退回投稿人，保留接收条目。</div>`)+floor('by',7,'2025-03-30 17:38',`<p>行，先不点名。我回头把原件和转发的分开放。</p><p>另外小范上周说的“复查回执”，有人知道放哪儿吗？我只见过班里的统计表，医务室那份没见着。</p>`);
 case 'lights':return floor('jie',1,'2025-03-29 18:03',`<p>终于不用摸黑接水了。上周有个人举着洗发水瓶站那儿等灯亮，我以为新型祈福。</p>`)+floor('ashui',2,'2025-03-29 18:11',`<p>后门那台刷卡机的钟也该修。13号那个周四我排你后面，你读20:43，我表上才41。值班的说显示快两分钟，扣钱记录走服务器，让我们别照那个钟赶晚点名。</p>`)+floor('jie',3,'2025-03-29 18:15',`<p>就是${FACTS.terminal}那台。难怪我每次以为自己迟到了。${a('canteen/index.html?view=card','补小票的入口')}在这，手机进不去，机房能开。</p>`)+floor('yida',4,'2025-03-29 18:22',`<p>灯亮了挺好。建议厕所也放个纸巾架，某些人能少一点人生难题。</p>`);
 case 'notebook':return floor('ashui',1,'2025-03-24 12:18',`<p>蓝皮，封面蹭了块白的。夹着领稿条，我没看笔记。下次自己的东西自己拿，老师一叠起来又找不到。</p><div class="inline-slip" id="stub" data-read="stub">禾声 · 领稿条<br>本周校对：<strong>第${FACTS.issue}期</strong>　收稿日：<strong>03月23日</strong><br>第${FACTS.nextIssue}期为下周预告样张，暂不开放阅览。<br>公共阅览按当期领稿条，不用个人学号。</div>`)+floor('jie',2,'2025-03-24 12:24',`<p>by的吧。他语文只剩封皮是新的。</p>`)+floor('by',3,'2025-03-24 12:39',`<p>是我的。别扔，条子我还有用。午休后去拿。</p>`)+floor('feixing',4,'2025-03-24 18:26',`<p>条上日期和期号别看错。${a('index.html?thread=archive','阅览说明')}还在置顶归档里。</p>`);
 case 'archive':return floor('feixing',1,'2025-03-23 19:30',`<div data-read="readRules"><p>编辑柜的共用阅览号继续用，不用再发学号给我。只读去标识稿件，个人附件还是退回本人。</p><blockquote>阅览凭证：校刊英文缩写 HS + 收稿月日（四位）+ 当周期号（两位）。<br>日期看回执，期号看本周领稿条。预告样张不算本期。</blockquote><p>本次回执日期03月23日。有人老把下一期的封面当成这期，请先看${a('index.html?thread=notebook','蓝皮笔记那张领稿条')}。</p><p>${a('pan/index.html?folder=editor','青禾资料柜 / 校刊接收柜')}。不是你的原稿别改名，更别整包搬出去。</p></div>`)+floor('ashui',2,'2025-03-23 19:55',`<p>16期打印了两份预览，17只是老师看选题。今天来取稿的别拿错。</p>`);
 case 'meal':return floor('jie',1,'2025-03-13 21:24',`<p>车仔面两份，清汤一份，饭团一个，都在桌上了。谁叫我带饭团来着？我洗个澡出来它还在。</p><p>火鸡面那碗也在桌上，我自己拆的。by帮我拌的时候别一口给我吃完。</p><figure id="table"><img class="desk-photo" src="assets/dorm-table.webp" alt="桌上一碗红色拌面、一小碗清汤、透明袋中的饭团和一个水杯" loading="lazy" data-read="tablePhoto" data-snapshot="3月13日宿舍桌面照片：红色拌面、独立小碗清汤、袋装饭团；照片只能显示拍到的物品，不证明每个人吃了多少。"><figcaption style="font-size:11px;color:#999">照片是杰哥回寝时拿那部旧手机拍的。别问怎么带进来的。</figcaption></figure><p>小票在${a('canteen/index.html?view=card','一卡通补打页面')}，我的卡尾号0327，今天开了临时只读回执，查03-13就行。</p>`)+floor('yida',2,'2025-03-14 12:13',`<p>饭团我的，我没看见在本子底下。清汤也是我的，面你们分吧。</p>`)+floor('by',3,'2025-03-14 12:40',`<p>拌匀了。乌鸡那口比我大，你去问他。</p>`)+floor('jie',4,'2025-03-14 12:56',`<p>行，洗澡十分钟，出来少半碗。</p>`);
 case 'printing':return floor('zhugui',1,'2025-03-21 07:12',`<p>下午学生会把老打印机挪去看台后面。有空帮阉鸡一下，别让他一个人抬。</p><p>禾声那摞待印稿还在电脑上，别顺手关电源。</p>`)+floor('mj',2,'2025-03-24 18:15',`<p>搬机器拍进相册了。BV号 <span class="native-code">${FACTS.bv}</span>，片名就叫“春季运动会”。网盘里有交接场记。</p>`)+floor('ashui',3,'2025-03-25 18:20',`<p>朱贵你不是请假？我还以为那天轮到你了。</p>`)+floor('zhugui',4,'2025-03-25 18:33',`<div id="leave" data-read="leaveClaim"><p>我那天请的全天假，从早到晚都不在学校。先别算我头上，打印值班本也不总是按表来的。</p></div>`)+floor('feixing',5,'2025-03-25 19:02',`<p>打印任务导出要本人确认后再给，不在这里乱发。接触过机器和改过稿件不是一个事。</p>`);
 case 'photos':return floor('feixing',1,'2025-03-19 18:44',`<p>益达那个小信封，里面三张旧照片，稿件不收了。目录我留着，信封你自己拿走。</p><p>${a('pan/index.html?file=photoIndex','退回照片袋目录')}是公开索引，没有信的内容。别把私人附件往论坛贴。</p>`)+floor('yida',2,'2025-03-19 19:01',`<p>收到，那个F1018就别留副本了。新传的不是我的，别一块删。</p>`)+floor('by',3,'2025-03-19 19:16',`<p>你们不是一件事就分开说，我还以为全在一个压缩包。</p>`);
 case 'sports':return floor('mj',1,'2025-03-24 18:06',`<p>机位B这回相机电池一般，挑照片剪了个相册，不是全程录像。高三就拍到边上那几个人，没去给你们教室偷拍。</p><p>${a('video/index.html?v='+FACTS.bv,'春季运动会 / 摄影社机位B')}，BV号 <span class="native-code">${FACTS.bv}</span>。原片袋怎么取在简介里。</p>`)+floor('yanji',2,'2025-03-24 18:30',`<p>你把搬机器也剪进去了。我脸都没拍到，挺好。</p>`)+floor('mj',3,'2025-03-24 18:39',`<p>反正背影。登记写清楚了，03-24是我上传，不是开运动会那天。</p>`);
 default:return floor('feixing',1,'2025-03-01 18:00',`<p>高三交流版不发实名病历，不转未经核实的名单。正常求助、失物、校刊投稿照常。</p><p>旧帖按关键词检索，别反复顶起过期信息。</p>`);
}}
const typo={夜霄:'夜宵',夜肖:'夜宵',帐单:'账单',打卬:'打印',旧相片:'旧照片',照相:'摄影',校看:'校刊'};
function list(query){const q=normalize(query),fixed=typo[q],term=fixed||q;let results=q?topics.filter(t=>[t.title,PEOPLE[t.who].name,...t.keywords].some(k=>normalize(k).includes(term)||term.length>1&&term.includes(normalize(k)))):topics.slice(0,4);if(q===FACTS.bv.toLowerCase())return `<p class="crumb">搜索 / ${esc(query)}</p><div class="query-note">摄影社在旧帖中引用了这个视频号：${a('video/index.html?v='+FACTS.bv,'春季运动会 / 机位B')}。</div>`;return `<p class="crumb">⌂ ${a('index.html','论坛首页')} › 高三交流${q?' › 搜索':''}</p><section class="board-head"><div class="board-icon">禾</div><div><h1>高三交流</h1><p>今日 <b>7</b>　主题 <b>1248</b>　排名 <b>2</b>　版主：飞星</p></div></section><p class="board-description">作业、晚饭、失物，先搜一下再发。病历不要带名字，别拿室友开这类玩笑。</p><div class="board-tools"><span>${q?'搜索结果：'+esc(query):'最近主题　｜　精华　｜　公告'}</span><span>最后回复 ↓</span></div>${fixed?`<div class="query-note">按“${esc(fixed)}”查找。${a('index.html?q='+encodeURIComponent(q),'保留原词重新搜索')}</div>`:''}<div class="topic-list"><div class="list-label">${q?results.length+' 条匹配主题':'近期置顶与日常'}</div>${results.map(t=>`<article class="topic-row"><div class="topic-mark">${t.tag?'▴':'▤'}</div><div>${tag(t.tag)}${a('index.html?thread='+t.id,esc(t.title))}<div class="topic-meta">高三交流 · ${t.date}　${t.views}人看过</div></div><div class="topic-author">${PEOPLE[t.who].name}<br><span style="color:#aaa">2025-${t.date}</span></div><div class="topic-replies">${t.replies}<br><small>回复</small></div><div class="topic-last">${t.id==='reports'?'by':PEOPLE[t.who].name}<br><span style="color:#aaa">${t.date} 18:26</span></div></article>`).join('')||`<div class="empty">没找到“${esc(query)}”。<p>试试少写几个字，或按事件检索：${['夜宵','照片','打印','摄影社','校刊'].map(w=>a('index.html?q='+encodeURIComponent(w),w)).join('　')}。</p></div>`}</div><div class="bbs-pagination">共 ${q?results.length:1248} 个主题 <span>1</span> ${q?'':'近期浏览 / 历史主题请用站内搜索'}</div>`;}
const id=params.get('thread');if(id){const t=topics.find(t=>t.id===id);app.innerHTML=`<p class="crumb">⌂ ${a('index.html','论坛首页')} › 高三交流 › ${esc(t?.title||'版务公告')}</p><div class="thread-title"><h1>${tag(t?.tag)}${esc(t?.title||'高三交流版使用说明')}</h1><small>查看 ${t?.views||315}　｜　回复 ${t?.replies||0}</small></div>${bodies(id)}<div class="bbs-pagination">${a('index.html','返回版面')}　<span>1</span></div>`;document.title=(t?.title||'版务公告')+' - 青禾论坛';}else app.innerHTML=list(params.get('q')||'');
const {bindReading}=await start('forum');bindReading(app);if(location.hash)document.querySelector(location.hash)?.scrollIntoView();document.addEventListener('click',e=>{if(e.target.matches('[data-like]')){e.target.textContent=e.target.textContent==='已赞'?'赞':'已赞';}if(e.target.matches('[data-report]')){e.target.textContent='已交版务';e.target.disabled=true;}});
